REVIEW_SCHEMA = obj_schema({'question':Q})

def clean_question(value, prompt_limit=600, reference_limit=800):
    if not isinstance(value,dict):raise ValueError('Actividad incompleta.')
    out={'prompt':compact(value.get('prompt'),prompt_limit),
         'reference':compact(value.get('reference'),reference_limit),
         'kind':compact(value.get('kind'),40)}
    if isinstance(value.get('observable_dimensions'),list):
        out['observable_dimensions']=list(dict.fromkeys(
            compact(item,40) for item in value['observable_dimensions']
            if compact(item,40) in ALLOWED_DIMENSIONS))
    if not out['prompt'] or not out['reference'] or not out['kind']:
        raise ValueError('Actividad incompleta.')
    return out

def validate_targeted_question(question, target_dimension):
    expected_kind=TARGETED_ACTIVITY_FAMILIES[target_dimension]
    if question.get('kind')!=expected_kind or question.get('observable_dimensions')!=[target_dimension]:
        raise ValueError(
            f'La actividad para {target_dimension} debe usar kind {expected_kind} '
            f'y observar únicamente {target_dimension}.')
    return question

def gemini(prompt, schema, max_tokens=2000):
    key = os.getenv('GEMINI_API_KEY','').strip()
    if not key:raise ValueError('Falta GEMINI_API_KEY en la terminal del servidor.')
    with LOCK:
        today=date.today().isoformat()
        if CALLS[today]>=LIMIT:raise ValueError('Límite local alcanzado; continúa con contenido guardado.')
        CALLS[today]+=1
    payload={'systemInstruction':{'parts':[{'text':SYSTEM}]},
             'contents':[{'role':'user','parts':[{'text':prompt}]}],
             'generationConfig':{'responseMimeType':'application/json',
                                 'responseSchema':schema,'maxOutputTokens':max_tokens}}
    req=urllib.request.Request(
      f'https://generativelanguage.googleapis.com/v1beta/models/{MODEL}:generateContent',
      data=json.dumps(payload,ensure_ascii=False).encode('utf-8'),
      headers={'Content-Type':'application/json','x-goog-api-key':key},method='POST')
    try:
        with urllib.request.urlopen(req,timeout=90) as resp:answer=json.load(resp)
    except urllib.error.HTTPError as exc:
        try:detail=json.load(exc).get('error',{}).get('message','')
        except (ValueError,TypeError):detail=''
        if exc.code==429:raise ValueError('Gemini aplicó un límite de solicitudes (429); revisa la cuota del proyecto.')
        raise ValueError(f'Gemini rechazó la solicitud ({exc.code}): {compact(detail,260)}')
    except (TimeoutError,socket.timeout,urllib.error.URLError):
        raise ValueError('Gemini tardó demasiado o se perdió la conexión.')
    try:
        candidate=answer['candidates'][0]
        text=''.join(x.get('text','') for x in candidate['content']['parts'])
        return json.loads(text)
    except (IndexError,KeyError,TypeError,ValueError):
        reason=(answer.get('candidates') or [{}])[0].get('finishReason','desconocido')
        raise ValueError(f'Gemini devolvió una salida incompleta ({reason}). No se guardó progreso.')

def validated_map(raw):
    if not isinstance(raw,dict) or not isinstance(raw.get('nodes'),list):
        raise ValueError('Mapa de competencias inválido.')
    nodes=[]
    for item in raw['nodes'][:12]:
        if not isinstance(item,dict):continue
        index=len(nodes)+1
        q=item.get('probe',{})
        try:probe=clean_question(q,500,700)
        except ValueError:continue
        try:level=max(0,min(7,int(item.get('level',index-1))))
        except (TypeError,ValueError):level=min(7,index-1)
        nodes.append({'id':f'n{index}','name':compact(item.get('name'),90),
          'outcome':compact(item.get('outcome'),160),'level':level,
          'kind':compact(item.get('kind'),30),
          'prerequisites':item.get('prerequisites',[]),
          'probe':probe})
    if len(nodes)<5 or any(not x['name'] for x in nodes):raise ValueError('Mapa incompleto; describe una meta más concreta.')
    ids={n['id'] for n in nodes}
    for n in nodes:
        raw_deps=n['prerequisites'] if isinstance(n['prerequisites'],list) else []
        n['prerequisites']=list(dict.fromkeys(d for d in raw_deps if d in ids and d!=n['id']))
    colors={}
    def visit(nid):
        if colors.get(nid)==1:raise ValueError('El mapa generó un ciclo de prerrequisitos.')
        if colors.get(nid)==2:return
        colors[nid]=1
        for dep in next(n for n in nodes if n['id']==nid)['prerequisites']:visit(dep)
        colors[nid]=2
    for n in nodes:visit(n['id'])
    return nodes

def validated_coverage(raw, nodes):
    allowed=ALLOWED_DIMENSIONS
    ids={n['id'] for n in nodes}; by_node={n['id']:n for n in nodes}; out=[]; seen=set()
    for item in raw.get('coverage',[]) if isinstance(raw,dict) and isinstance(raw.get('coverage',[]),list) else []:
        if not isinstance(item,dict):continue
        nid=compact(item.get('id'),40)
        if nid not in ids or nid in seen:continue
        seen.add(nid); dims=[]
        for dim in item.get('dimensions',[]) if isinstance(item.get('dimensions',[]),list) else []:
            if not isinstance(dim,dict):continue
            did=compact(dim.get('id'),40)
            if did in allowed and did not in {x['id'] for x in dims}:
                dims.append({'id':did,'name':compact(dim.get('name'),80) or did,'required':bool(dim.get('required',True)),'status':'UNKNOWN','evidence':[]})
        if not dims:dims=[{'id':'conceptual','name':'Comprensión','required':True,'status':'UNKNOWN','evidence':[]},{'id':'direct_application','name':'Aplicación','required':True,'status':'UNKNOWN','evidence':[]}]
        deps=item.get('prerequisites',[]) if isinstance(item.get('prerequisites',[]),list) else []
        out.append({'id':nid,'name':compact(item.get('name'),100) or by_node[nid]['name'],'kind':compact(item.get('kind'),30) or by_node[nid]['kind'],'priority':compact(item.get('priority'),20) or 'important','prerequisites':[d for d in deps if d in ids and d!=nid],'contexts':[compact(x,100) for x in (item.get('contexts',[]) if isinstance(item.get('contexts',[]),list) else []) if compact(x,100)][:6],'status':'UNKNOWN','confidence':0.0,'last_evidence':None,'dimensions':dims,'updates':[]})
    have={x['id'] for x in out}
    for n in nodes:
        if n['id'] not in have:out.append({'id':n['id'],'name':n['name'],'kind':n['kind'],'priority':'important','prerequisites':n['prerequisites'],'contexts':[],'status':'UNKNOWN','confidence':0.0,'last_evidence':None,'dimensions':[{'id':'conceptual','name':'Comprensión','required':True,'status':'UNKNOWN','evidence':[]},{'id':'direct_application','name':'Aplicación','required':True,'status':'UNKNOWN','evidence':[]}],'updates':[]})
    return out

def make_coverage_map(data):
    goal=compact(data.get('goal'),160); context=compact(data.get('context'),350)
    if len(goal)<5:raise ValueError('Describe una meta concreta.')
    raw=gemini(f'Meta: {goal}. Contexto no confidencial: {context}. Construye UNA VEZ el grafo de aprendizaje y una cobertura persistente. Genera 6-8 nodos ids n1,n2 con prerrequisitos sin ciclos. Para cada nodo devuelve coverage con prioridad blocker, important, secondary u optional, contextos de aplicación y SOLO dimensiones relevantes: conceptual, recognition, variables, units, equation_manipulation, method_selection, direct_application, contextual_application, interpretation, transfer, procedure, memory o self_explanation. Cada probe declara kind y observable_dimensions coherentes con lo que pregunta; usa solo dimensiones de la lista anterior. Distingue conocimiento base de contexto. No uses una checklist fija ni redescubras componentes ya cubiertos en futuras interacciones. Incluye matemática, ecuaciones o unidades solo si la meta lo requiere. No inventes parámetros técnicos locales.',MAP_SCHEMA,4200)
    nodes=validated_map(raw)
    return {'nodes':nodes,'coverage':validated_coverage(raw,nodes),'map_version':1}

def make_map(data):
    return make_coverage_map(data)


def lesson_adaptation(attempts, target_dimension=None):
    """Choose teaching depth from recorded attempts, never from client mastery claims."""
    related = []
    for item in (attempts if isinstance(attempts, list) else [])[:5]:
        if not isinstance(item, dict):
            continue
        event = item.get('event') if isinstance(item.get('event'), dict) else {}
        observed = event.get('observed_dimensions', [])
        if target_dimension and (not isinstance(observed, list) or target_dimension not in observed):
            continue
        related.append((item, event))
    if not related:
        return ('initial', 'Sin evidencia previa pertinente; enseñar los fundamentos.',
                'Microlección desde nivel cero')
    recent, event = related[0]
    if recent.get('result') in ('PARTIAL', 'MISCONCEPTION'):
        return ('repair', 'El intento más reciente mostró una dificultad; abordar ese error.',
                'Microlección correctiva: explica el principio que causó el error y un ejemplo diferente')
    if (recent.get('help_used') or 0) > 0 or (recent.get('result') == 'CORRECT' and event.get('is_independent') is not True):
        return ('scaffold', 'Hay desempeño asistido o no independiente; retirar apoyo gradualmente.',
                'Microlección de apoyo gradual: recordar el principio necesario, modelar un paso y retirar ayuda')
    if recent.get('result') == 'CORRECT' and event.get('is_independent') is True and not event.get('corrected') and (recent.get('help_used') or 0) == 0:
        return ('consolidate', 'Existe un acierto independiente previo; falta comprobarlo en otra situación.',
                'Microlección de consolidación: no repetir toda la introducción; centrarse en el principio pendiente y un caso distinto')
    return ('initial', 'No hay evidencia independiente reciente que justifique saltarse los fundamentos.',
            'Microlección desde nivel cero')

def make_lesson(data):
    goal=compact(data.get('goal'),160); name=compact(data.get('name'),90)
    parent=compact(data.get('parent'),100)
    target_dimension=compact(data.get('target_dimension'),40)
    if not goal or not name:raise ValueError('Falta meta o concepto.')
    if target_dimension and target_dimension not in TARGETED_ACTIVITY_FAMILIES:
        raise ValueError('La dimensión pendiente no tiene una familia de actividad dirigida.')
    target_instruction='';memory_context='';memory_result={'reason':None,'sources':[],'attempts':[]}
    if target_dimension:
        target_kind=TARGETED_ACTIVITY_FAMILIES[target_dimension]
        target_instruction=(f' La práctica GUIDED e INDEPENDENT debe evaluar específicamente {target_dimension}; '
          f'ambas usan kind exacto {target_kind} y observable_dimensions exactamente ["{target_dimension}"]. '
          'No atribuyas otras dimensiones a esas dos actividades.')
    profile_id=compact(data.get('profile_id'),80);goal_id=compact(data.get('goal_id'),100);node_id=compact(data.get('node_id'),100)
    if profile_id and goal_id and node_id:
        loaded=memory().load(profile_id)
        memory_result=memory().relevant_memory(profile_id,goal_id,node_id,target_dimension or None,5)
        bounded={'preferences':loaded['preferences'],'recent_attempts':[{'attempt_id':x['attempt_id'],'phase':x['phase'],'result':x['result'],'help_used':x['help_used'],'response_text':compact(x.get('response_text'),240)} for x in memory_result['attempts']]}
        memory_context=' Memoria pertinente y preferencias explícitas: '+compact(json.dumps(bounded,ensure_ascii=False),1800)+'. '
    adaptation_mode,adaptation_reason,lesson_depth=lesson_adaptation(memory_result.get('attempts',[]),target_dimension or None)
    raw=gemini(f'Meta: {goal}; aprender ahora: {name}; concepto al que regresaremos: {parent or goal}. '
      f'{lesson_depth}: 1 explicación intuitiva de máximo 70 palabras, '
      '2 ejemplo resuelto en pasos, 3 error común, 4 pregunta de comprensión simple, '
      '5 ejercicio guiado, 6 caso independiente diferente, 7 pregunta de integración con la meta. '
      'Cada pregunta debe tener criterios de respuesta, kind y observable_dimensions limitadas a lo que realmente observa.'+target_instruction+
      ' Adapta el método si es fórmula, idioma o procedimiento. '+
      memory_context+'No inventes detalles técnicos locales.',STAGE_SCHEMA,1900)
    if not isinstance(raw,dict):raise ValueError('Microlección inválida.')
    out={k:compact(raw.get(k),1100) for k in ('explanation','example','common_error')}
    for k in ('check','guided','independent','integration'):
        out[k]=clean_question(raw.get(k,{}),600,700)
    if target_dimension:
        validate_targeted_question(out['guided'],target_dimension)
        validate_targeted_question(out['independent'],target_dimension)
        out['target_dimension']=target_dimension
    out['memory_reason']=memory_result['reason'];out['memory_sources']=memory_result['sources']
    out['adaptation_mode']=adaptation_mode;out['adaptation_reason']=adaptation_reason
    if not all(out[k] for k in ('explanation','example','common_error')) or not all(q['prompt'] and q['reference'] for q in (out[k] for k in ('check','guided','independent','integration'))):
        raise ValueError('Microlección incompleta; no se guardó.')
    return out

def evaluate(data):
    answer=compact(data.get('answer'),1800)
    q=data.get('question',{})
    if not isinstance(q,dict) or not compact(q.get('prompt')):raise ValueError('Pregunta inválida.')
    if not answer:raise ValueError('Escribe tu idea o usa «No sé».')
    if answer.lower().strip(' .!') in ('no sé','no se','no lo sé','no lo se','ni idea'):
        return {'status':'UNKNOWN','feedback':'Está bien no saberlo aún. Vamos a construirlo.','error_type':'lack_of_exposure','hint':''}
    raw=gemini('Pregunta: '+compact(q.get('prompt'),600)+'; criterios: '+compact(q.get('reference'),700)+
      '; intento: '+answer+'; fase: '+compact(data.get('phase'),30)+
      '. Valora razonamiento y soluciones alternativas justificadas. '
      'status debe ser CORRECT, PARTIAL o MISCONCEPTION; nunca marques correcto un mero eco del enunciado. '
      'Da feedback breve y una pista mínima sin revelar toda la solución. '
      'error_type: conceptual, prerequisite, formula_selection, variable_identification, units, algebra, arithmetic, procedure, interpretation, memory, application, transfer, attention o none.',EVAL_SCHEMA,500)
    status=raw.get('status') if isinstance(raw,dict) else None
    if status not in ('CORRECT','PARTIAL','MISCONCEPTION'):raise ValueError('Evaluación incompleta.')
    return {k:compact(raw.get(k),650) for k in ('status','feedback','error_type','hint')}

def review_question(data):
    if data.get('target_dimension'):
        return evidence_confirmation({**data, 'previous': data.get('previous_questions', []), 'difficulty': 'standard'})
    goal=compact(data.get('goal'),160);concept=compact(data.get('concept'),90)
    if not goal or not concept:raise ValueError('Falta meta o concepto.')
    raw=gemini(f'Objetivo: {goal}; concepto: {concept}; nivel de repaso: {compact(data.get("level"),5)}. '
      'Crea UNA pregunta nueva de recuperación que aplique el mismo concepto a otro contexto. Declara kind y observable_dimensions limitadas a lo que la pregunta observa. '
      'No repitas: '+compact(data.get('previous'),300)+'. Respuesta de referencia breve.',REVIEW_SCHEMA,550)
    q=raw.get('question',{}) if isinstance(raw,dict) else {}
    try:q=clean_question(q,700,700)
    except ValueError:raise ValueError('Pregunta de repaso incompleta.')
    return {'question':q}

def evidence_confirmation(data):
    """Generate only the missing check; policy and sufficiency remain local."""
    goal=compact(data.get('goal'),160);concept=compact(data.get('concept'),90)
    target=compact(data.get('target_dimension'),40)
    if not goal or not concept or target not in CONFIRMATION_KINDS:
        raise ValueError('Falta una meta, concepto o dimensión de comprobación válida.')
    previous=data.get('previous',[])
    if not isinstance(previous,list) or len(previous)>20 or any(not isinstance(p,str) or len(p)>700 for p in previous):
        raise ValueError('El historial de preguntas de comprobación es inválido.')
    difficulty=data.get('difficulty','standard')
    if difficulty not in ('standard','challenge'):raise ValueError('Dificultad inválida.')
    challenge=(' Añade una restricción relevante y pide justificar una decisión dentro de esta habilidad; no introduzcas prerrequisitos nuevos ni lo llames transferencia.' if difficulty=='challenge' else '')
    kind=CONFIRMATION_KINDS[target]
    prompt=(f'Meta: {goal}; competencia: {concept}. Crea UNA comprobación independiente '
      f'de {target}, kind exacto {kind}, observable_dimensions exactamente ["{target}"]. '
      'Pregunta breve con criterio de respuesta. No muestres solución ni pistas en el enunciado. '
      'Cambia el razonamiento o representación, no solo cifras o nombres. No declares transferencia, '
      'retención ni dominio. No repitas ni parafrasees estas preguntas: '+json.dumps(previous,ensure_ascii=False)+'. '
      'No inventes datos técnicos locales.'+challenge)
    raw=gemini(prompt,REVIEW_SCHEMA,700)
    q=clean_question(raw.get('question') if isinstance(raw,dict) else None,700,700)
    if q['kind']!=kind or q.get('observable_dimensions')!=[target]:
        raise ValueError('La comprobación no respeta la dimensión y familia solicitadas.')
    def fingerprint(value):
        return re.sub(r'[^a-z0-9áéíóúüñ]+',' ',unicodedata.normalize('NFKC',value).lower()).strip()
    if not fingerprint(q['prompt']) or fingerprint(q['prompt']) in {fingerprint(p) for p in previous}:
        raise ValueError('La comprobación repite una pregunta anterior.')
    return {'question':q}

MICRO_SCHEMA=obj_schema({'focus':T,'explanation':T,'representation':T,
 'steps':{'type':'ARRAY','items':Q},'transfer':Q})
REPAIR_SCHEMA=obj_schema({'explanation':T,'step':Q})

def micro_start(data):
    question=data.get('question',{})
    if not isinstance(question,dict):raise ValueError('Falta la pregunta original.')
    prompt=('Objetivo: '+compact(data.get('goal'),160)+'; problema original: '+compact(question.get('prompt'),500)+
      '; intento que falló: '+compact(data.get('answer'),700)+'; feedback: '+compact(data.get('feedback'),350)+
      '; tipo de error: '+compact(data.get('error_type'),40)+'. Aísla SOLO la pieza mínima que falta. '
      'Explica en máximo 55 palabras y crea TRES microinteracciones cortas y diferentes: '
      'reconocimiento, predicción y aplicación; después UNA transferencia al problema original. '
      'Cada una con criterios de respuesta, kind y observable_dimensions limitadas a lo que realmente observa. No repitas el problema original. Representación textual solo si ayuda. '
      'Nada de datos específicos de plantas desconocidas.')
    raw=gemini(prompt,MICRO_SCHEMA,1300)
    if not isinstance(raw,dict) or not isinstance(raw.get('steps'),list) or len(raw['steps'])<3:
        raise ValueError('La IA no creó la microtutoría completa.')
    return {'focus':compact(raw.get('focus'),100),'explanation':compact(raw.get('explanation'),500),
      'representation':compact(raw.get('representation'),280),
      'steps':[clean_question(q,500,500) for q in raw['steps'][:3]],'transfer':clean_question(raw.get('transfer',{}),500,500)}

def micro_repair(data):
    prompt=('Trabaja SOLO esta dificultad: '+compact(data.get('focus'),120)+'; microinteracción: '+
      compact(data.get('question'),400)+'; respuesta: '+compact(data.get('answer'),500)+'; error: '+
      compact(data.get('feedback'),350)+'. Da UNA pista muy breve y una NUEVA microinteracción '
      'que cambie el ejemplo o la representación, sin revelar toda la respuesta. Incluye criterio de respuesta, kind y observable_dimensions limitadas a lo que observa.')
    raw=gemini(prompt,REPAIR_SCHEMA,450)
    q=raw.get('step',{}) if isinstance(raw,dict) else {}
    try:q=clean_question(q,500,500)
    except ValueError:raise ValueError('No se pudo preparar otra interacción.')
    return {'explanation':compact(raw.get('explanation'),350),'step':q}


