def make_micro_context(data):
    q=data.get('question',{})
    if not isinstance(q,dict) or not compact(q.get('prompt')): raise ValueError('Falta la pregunta del contexto.')
    nearby=data.get('nearby_prerequisites',[])
    if not isinstance(nearby,list):nearby=[]
    raw=gemini('Problema padre: '+compact(q.get('prompt'),600)+'; respuesta original: '+compact(data.get('answer'),900)+
      '; feedback: '+compact(data.get('feedback'),400)+'; tipo de error: '+compact(data.get('error_type'),40)+
      '; prerrequisitos cercanos permitidos: '+compact(json.dumps(nearby[:6],ensure_ascii=False),1000)+
      '. Diseña un episodio de reparación verificable. Propón entre una y tres hipótesis como máximo; usa SUSPECTED salvo evidencia inequívoca, no inventes déficits. '
      'Cada hipótesis necesita gap_id, concepto, razón, evidencia motivadora, confianza 0..1 y estado. Crea hasta tres comprobaciones diagnósticas breves asociadas por gap_id. '
      'Crea CHECK, GUIDED e INDEPENDENT como preguntas distintas entre sí y distintas del problema padre. CHECK comprueba el prerrequisito; GUIDED admite apoyo; INDEPENDENT exige ejecución nueva sin ayuda. '
      'Crea un parent_retest nuevo pero claramente relacionado y un transfer_check con cambio significativo de contexto, representación o decisión. '
      'Describe la diferencia en transfer_novelty_basis y declara transfer_novelty_status INDETERMINATE; la política local verifica la novedad. Todas las preguntas requieren criterio de respuesta, kind y observable_dimensions limitadas a lo que observan. No inventes parámetros locales.',REPAIR_EPISODE_SCHEMA,2600)
    if not isinstance(raw,dict):raise ValueError('Plan de reparación incompleto.')
    gaps=raw.get('suspected_gaps',[]);checks=raw.get('diagnostic_checks',[]);activities=raw.get('repair_activities',{})
    if not isinstance(gaps,list) or not 1<=len(gaps)<=3 or not isinstance(checks,list) or not 1<=len(checks)<=3 or not isinstance(activities,dict):raise ValueError('El diagnóstico de reparación no respeta los límites.')
    allowed_nodes={compact(x.get('id'),40) for x in nearby if isinstance(x,dict)}
    cleaned_gaps=[];gap_ids=set()
    for index,item in enumerate(gaps):
        if not isinstance(item,dict):raise ValueError('Hipótesis de reparación inválida.')
        gap_id=compact(item.get('gap_id'),80) or f'gap-{index+1}'
        if gap_id in gap_ids:raise ValueError('El diagnóstico repite una laguna.')
        gap_ids.add(gap_id)
        try:confidence=max(0.0,min(1.0,float(item.get('confidence',0))))
        except (TypeError,ValueError):confidence=0.0
        node_id=compact(item.get('node_id'),40)
        cleaned_gaps.append({'gap_id':gap_id,'node_id':node_id if node_id in allowed_nodes else None,'concept':compact(item.get('concept'),140) or 'Laguna por determinar','reason':compact(item.get('reason'),400),'motivating_evidence':compact(item.get('motivating_evidence'),500),'confidence':confidence,'status':'SUSPECTED'})
    cleaned_checks=[]
    for index,item in enumerate(checks):
        if not isinstance(item,dict):raise ValueError('Comprobación diagnóstica inválida.')
        gap_id=compact(item.get('gap_id'),80)
        if gap_id not in gap_ids:gap_id=cleaned_gaps[min(index,len(cleaned_gaps)-1)]['gap_id']
        cleaned_checks.append({'gap_id':gap_id,'question':clean_question(item.get('question',{}),600,800)})
    cleaned_activities={stage:clean_question(activities.get(stage,{}),600,800) for stage in ('CHECK','GUIDED','INDEPENDENT')}
    parent_retest=clean_question(raw.get('parent_retest',{}),600,800);transfer_check=clean_question(raw.get('transfer_check',{}),600,800)
    prompts=[compact(q.get('prompt'),600).casefold() for q in [q,*[x['question'] for x in cleaned_checks],*cleaned_activities.values(),parent_retest,transfer_check]]
    if len(prompts)!=len(set(prompts)):raise ValueError('El plan repite una actividad del episodio.')
    novelty=raw.get('transfer_novelty_status')
    basis=compact(raw.get('transfer_novelty_basis'),500)
    # A generator's declaration is a candidate, not independent novelty verification.
    novelty='INDETERMINATE'
    return {'suspected_gaps':cleaned_gaps,'diagnostic_checks':cleaned_checks,'repair_activities':cleaned_activities,'parent_retest':parent_retest,'transfer_check':transfer_check,'transfer_novelty_status':novelty,'transfer_novelty_basis':basis}

def micro_step(data):
    ctx=data.get('context',{});q=ctx.get('question',{})
    if not isinstance(ctx,dict) or ctx.get('status') not in ('ACTIVE','RETURNING'):raise ValueError('El contexto no está activo.')
    if not isinstance(q,dict) or not q.get('prompt'):raise ValueError('Contexto sin pregunta.')
    return evaluate({'question':q,'answer':data.get('answer'),'phase':'MICRO_TUTOR'})

def micro_zoom(data):
    ctx=data.get('context',{})
    if not isinstance(ctx,dict):raise ValueError('Contexto padre inválido.')
    q=ctx.get('question',{})
    if not isinstance(q,dict) or not compact(q.get('prompt')):raise ValueError('Contexto padre inválido.')
    raw=gemini('Concepto: '+compact(ctx.get('concept'),100)+'; pregunta: '+compact(q.get('prompt'),350)+
        '; respuesta: '+compact(data.get('answer'),450)+'; error: '+compact(data.get('feedback'),200)+
        '. Haz zoom a una pieza menor. Explica y da ejemplo ANTES de una pregunta nueva con criterio. No inventes parámetros locales.',CONTEXT_SCHEMA,750)
    if not isinstance(raw,dict) or not compact(raw.get('objective')) or not compact(raw.get('concept')):
        raise ValueError('El zoom no generó un contexto completo.')
    child_q=raw.get('question',{})
    if not isinstance(child_q,dict) or not compact(child_q.get('prompt')) or not compact(child_q.get('reference')):
        raise ValueError('El zoom no generó una pregunta completa.')
    try:difficulty=max(0,min(7,int(raw.get('difficulty',0))))
    except (TypeError,ValueError):difficulty=0
    return {'context_id':'micro-'+str(time.time_ns()),'parent_context_id':compact(ctx.get('context_id'),80) or None,
        'objective':compact(raw['objective'],300),'concept':compact(raw['concept'],140),
        'question':{'prompt':compact(child_q['prompt'],600),'reference':compact(child_q['reference'],800),
                    'kind':compact(child_q.get('kind'),40)},
        'explanation':compact(raw.get('explanation'),650),'example':compact(raw.get('example'),600),
        'expected_answer':compact(raw.get('expected_answer'),800),'mastery_criteria':compact(raw.get('mastery_criteria'),500),
        'difficulty':difficulty,'status':'ACTIVE','attempts':0,'hints_used':0,'history':[]}


def context_status(data):
    ctx=data.get('context',{});status=data.get('status')
    if status not in ('ACTIVE','PAUSED','MASTERED','FAILED','NEEDS_DECOMPOSITION','RETURNING','INTEGRATING'):raise ValueError('Estado de contexto inválido.')
    return {'context_id':ctx.get('context_id'),'status':status,'mastery':data.get('mastery',0),'parent_context_id':ctx.get('parent_context_id')}

def map_update(data):
    component=compact(data.get('component_id'),40);reason=compact(data.get('reason'),400)
    if not component or not reason:raise ValueError('Falta componente o razón de MAP UPDATE.')
    return {'component_id':component,'reason':reason,'status':'RECORDED','at':time.time_ns()}

def profiles_list(data):
    return {'profiles':memory().profiles()}

def profile_create(data):
    return memory().create_profile(data.get('name'))

def profile_load(data):
    return memory().load(data.get('profile_id'))

def profile_save(data):
    return memory().save(data.get('profile_id'),data.get('store'),data.get('expected_revision'))

def profile_preferences(data):
    return {'preferences':memory().set_preferences(data.get('profile_id'),data.get('preferences'))}

def profile_history(data):
    return {'attempts':memory().history(data.get('profile_id'),data.get('goal_id'),data.get('node_id'),data.get('limit',100))}

def profile_import(data):
    return memory().import_store(data.get('profile_id'),data.get('store'))

def profile_export(data):
    return memory().export(data.get('profile_id'))

def profile_restore(data):
    return memory().restore(data.get('profile_id'),data.get('backup'))

def assessment_context(data):
    loaded=memory().load(data.get('profile_id'))
    goal=next((g for g in loaded['store']['goals'] if g['id']==data.get('goal_id')),None)
    if not goal:raise ValueError('La meta no pertenece al perfil seleccionado.')
    return goal

def assessment_task(data):
    goal=assessment_context(data)
    node=next((n for n in goal['nodes'] if n['id']==data.get('node_id')),None)
    if not node:raise ValueError('Habilidad no encontrada.')
    source=next((t for t in goal.get('authentic_tasks',[]) if t['task_id']==data.get('source_task_id')),None)
    purpose=data.get('purpose','application')
    if purpose=='transfer' and not any(a.get('task_id')==data.get('source_task_id') and assessment.all_met(a) for a in goal.get('authentic_attempts',[])):
        raise ValueError('Primero demuestra la tarea origen de forma independiente.')
    task=assessment.generate_task(goal['goal'],node,gemini,source['family'] if source else data.get('family'),source,purpose)
    return {'task':task}

_ASSESSMENT_CACHE={}
_ASSESSMENT_LOCK=threading.Lock()
def assessment_evaluate(data):
    goal=assessment_context(data)
    task=next((t for t in goal.get('authentic_tasks',[]) if t['task_id']==data.get('task_id')),None)
    if not task:raise ValueError('Guarda la tarea antes de evaluarla.')
    submission=data.get('submission')
    if not isinstance(submission,dict):raise ValueError('Respuesta inválida.')
    attempt_id=assessment.text(data.get('attempt_id'),150)
    # An idempotency key belongs to exactly one immutable submission and task.
    fingerprint=json.dumps({'task':task,'submission':submission},sort_keys=True,ensure_ascii=False)
    for attempt in goal.get('authentic_attempts',[]):
        if attempt.get('attempt_id')==attempt_id:
            if attempt.get('task_id')!=task['task_id'] or attempt.get('submission')!=submission:raise ValueError('El intento ya corresponde a otra respuesta.')
            return {'evaluation':attempt['evaluation']}
    key=(data.get('profile_id'),goal['id'],attempt_id)
    with _ASSESSMENT_LOCK:
        if key in _ASSESSMENT_CACHE:
            old,result=_ASSESSMENT_CACHE[key]
            if old!=fingerprint:raise ValueError('Colisión de identificador de intento.')
            return {'evaluation':result}
        result=assessment.evaluate_task(task,submission,attempt_id,gemini)
        source=next((t for t in goal.get('authentic_tasks',[]) if t['task_id']==task.get('source_task_id')),None)
        relation=assessment.novelty(task,source)
        source_attempt=next((a for a in reversed(goal.get('authentic_attempts',[])) if a.get('task_id')==task.get('source_task_id') and assessment.all_met(a)),None)
        result['relation']=relation
        result['source_attempt_id']=source_attempt['attempt_id'] if source_attempt else None
        result['transfer_eligible']=relation['status']=='VERIFIED_NEAR_TRANSFER' and source_attempt is not None
        _ASSESSMENT_CACHE[key]=(fingerprint,result)
        if len(_ASSESSMENT_CACHE)>200:_ASSESSMENT_CACHE.pop(next(iter(_ASSESSMENT_CACHE)))
    return {'evaluation':result}


ROUTES={'/api/assessment/task':assessment_task,'/api/assessment/evaluate':assessment_evaluate,'/api/map':make_map,'/api/lesson':make_lesson,
        '/api/evaluate':evaluate,'/api/review':review_question,'/api/confirmation':evidence_confirmation,'/api/micro/start':micro_start,'/api/micro/repair':micro_repair,'/api/context/create':make_micro_context,'/api/context/step':micro_step,'/api/context/zoom':micro_zoom,'/api/context/status':context_status,'/api/map/update':map_update,
        '/api/profiles/list':profiles_list,'/api/profile/create':profile_create,'/api/profile/load':profile_load,'/api/profile/save':profile_save,'/api/profile/preferences':profile_preferences,'/api/profile/history':profile_history,'/api/profile/import':profile_import,'/api/profile/export':profile_export,'/api/profile/restore':profile_restore}

class Handler(BaseHTTPRequestHandler):
    def respond(self,status,content,mime='application/json; charset=utf-8'):
        raw=content.encode() if isinstance(content,str) else json.dumps(content,ensure_ascii=False).encode()
        self.send_response(status);self.send_header('Content-Type',mime)
        self.send_header('Content-Length',str(len(raw)));self.send_header('Cache-Control','no-store')
        self.send_header('X-Content-Type-Options','nosniff')
        self.send_header('Content-Security-Policy',"default-src 'self' 'unsafe-inline';connect-src 'self';base-uri 'none'")
        self.end_headers();self.wfile.write(raw)
    def do_GET(self):
        if self.path=='/':self.respond(200,HTML,'text/html; charset=utf-8')
        elif self.path=='/api/health':self.respond(200,{'ok':True,'configured':bool(os.getenv('GEMINI_API_KEY')),'model':MODEL})
        else:self.respond(404,{'error':'No existe esta ruta.'})
    def do_POST(self):
        if self.path not in ROUTES:self.respond(404,{'error':'No existe esta ruta.'});return
        if self.headers.get('Origin') not in (None,f'http://{HOST}:{PORT}'):
            self.respond(403,{'error':'Origen no autorizado.'});return
        try:
            size=int(self.headers.get('Content-Length','0'))
            if not 0<size<=5*1024*1024:raise ValueError('Solicitud vacía o demasiado grande.')
            payload=json.loads(self.rfile.read(size))
            if not isinstance(payload,dict):raise ValueError('Se esperaba un objeto JSON.')
            self.respond(200,ROUTES[self.path](payload))
        except (ValueError,TypeError) as exc:self.respond(400,{'error':str(exc)})
        except Exception as exc:
            print('Error interno:',repr(exc),flush=True)
            self.respond(500,{'error':'Falló el servidor; revisa la terminal.'})

